r"""
Crescopus - test data for disputes, plus a fix to the disputes migration

  - sql/seed_dispute_test_data.sql: a Pocket Ledger x Harbour Digital
    partnership with a dispute in each state (needs the mockup test users).
  - sql/migration_ledger_disputes.sql (updated): deleting a whole
    partnership or account was blocked if it had a disputed or voided
    entry. Now it isn't. Re-run it; it's safe to re-run.

HOW TO USE
  Save next to wsgi.py and run:  python apply_dispute_test_data.py
  Then in the Supabase SQL editor run, in order:
    1. sql/migration_ledger_disputes.sql
    2. sql/seed_dispute_test_data.sql
"""
import base64, os, shutil, sys

FILES = [
    ("sql/migration_ledger_disputes.sql", ""),
    ("sql/seed_dispute_test_data.sql", "")
]
BACKUP = "_backup_apply_dispute_test_data"
NEXT = "in Supabase, run sql/migration_ledger_disputes.sql again (it has a fix), then run sql/seed_dispute_test_data.sql."

def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not os.path.isfile(os.path.join(root, "app", "__init__.py")) or not os.path.isfile(os.path.join(root, "wsgi.py")):
        sys.exit("Stopped: put this file in the Crescopus project folder (next to wsgi.py and the app folder), then run it again.")
    backup = os.path.join(root, BACKUP)
    changed = 0
    for rel, b64 in FILES:
        path = os.path.join(root, *rel.split("/"))
        data = base64.b64decode(b64)
        status = "new     "
        if os.path.exists(path):
            with open(path, "rb") as fh:
                if fh.read() == data:
                    print("same     " + rel)
                    continue
            dest = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            shutil.copy2(path, dest)
            status = "updated "
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        changed += 1
        print(status + " " + rel)
    print("\nDone - %d of %d files written." % (changed, len(FILES)))
    if os.path.isdir(backup):
        print("Originals of replaced files are in " + BACKUP + os.sep)
    if NEXT:
        print("Next: " + NEXT)

if __name__ == "__main__":
    main()
